struct iovec iov[2];
char buf_a[] = "Header: ";
char buf_b[] = "Payload data.";

iov[0].iov_base = buf_a;
iov[0].iov_len  = 8;
iov[1].iov_base = buf_b;
iov[1].iov_len  = 13;

int target_fd = 4;
off_t write_offset = 2048;

// Atomically write both buffers (A then B) starting at offset 2048.
// File descriptor's current offset is not updated.
ssize_t bytes_written = pwritev(target_fd, iov, 2, write_offset);
